const {chromium}=require('playwright');
const fs=require('fs');
(async()=>{
 const b=await chromium.launch({headless:true,channel:'msedge'});
 const p=await b.newPage({viewport:{width:1000,height:1000},storageState:'.bug02-browser.json'});
 const out='../answers/BUG-02/evidence/';
 const fixture=JSON.parse(fs.readFileSync(out+'bug-02-test-data.json','utf8'));
 const click=async l=>{await l.waitFor();await l.evaluate(el=>el.click())};
 await p.goto('http://localhost:3000/accounting');
 await click(p.getByRole('tab',{name:'Invoices',exact:true}));
 async function invoice(key,tc,file){
  const s=fixture.data.steps[tc];
  await click(p.getByRole('button',{name:'New invoice',exact:true}).first());
  await p.locator('#invCompany').click();
  await p.getByRole('option',{name:fixture.data.companies.find(c=>c.key===key).name,exact:true}).click();
  await p.getByLabel('Line 1 description').fill(s.lineDescription);
  await p.getByLabel('Line 1 quantity').fill(String(s.quantity));
  await p.getByLabel('Line 1 unit price').fill(s.unitPrice);
  await p.getByRole('button',{name:'Create draft',exact:true}).click();
  await p.getByRole('dialog').waitFor({state:'hidden'});
  const row=p.getByRole('row').filter({hasText:fixture.data.companies.find(c=>c.key===key).name});
  await click(row.getByRole('button',{name:'Issue',exact:true}));
  await row.getByText('sent',{exact:true}).waitFor();
  console.log(tc,await row.innerText());
  await p.screenshot({path:out+file,fullPage:true});
 }
 await invoice('VND','BUG-02-TC-01','tc-01-vnd-invoice.png');
 await click(p.getByRole('tab',{name:'Payments',exact:true}));
 await click(p.getByRole('button',{name:'Record payment',exact:true}).first());
 await p.locator('#payCompany').click();
 await p.getByRole('option',{name:fixture.data.companies[0].name,exact:true}).click();
 await p.locator('#payInvoice').click();
 await p.getByRole('option').filter({hasNotText:'No specific invoice'}).first().click();
 await p.locator('#payAmount').fill(fixture.data.steps['BUG-02-TC-02'].amount);
 await p.getByRole('dialog').getByRole('button',{name:'Record payment',exact:true}).click();
 await p.getByRole('dialog').waitFor({state:'hidden'});
 await click(p.getByRole('tab',{name:'Invoices',exact:true}));
 await p.getByRole('row').filter({hasText:fixture.data.companies[0].name}).getByText('partial',{exact:true}).waitFor();
 await p.screenshot({path:out+'tc-02-vnd-payment.png',fullPage:true});
 await invoice('USD','BUG-02-TC-03','tc-03-usd-invoice.png');
 await b.close();
})().catch(e=>{console.error(e);process.exit(1)});

